#pragma once

#include "endweave/protocol/block.h"
#include "endweave/protocol/version.h"

#include <algorithm>
#include <bedrock/protocol/nbt.hpp>
#include <cstdint>
#include <optional>
#include <span>
#include <string_view>
#include <utility>
#include <vector>

namespace endweave {

/** How one biome becomes the other version's across a hop: the id it takes, which is that of the
 * biome it is renamed to where the other version lacks it. Generated by tools/generate_mappings.py. */
struct BiomeUpdate {
    std::string_view name;
    std::uint32_t id;
    std::string_view rename = {};
    std::uint32_t new_id;
};

/** One hop's mappings as generated data: `block_states`, the block types whose states change; where
 * `To` lacks any of `From`'s items, `items`, their names, sorted; where `To` gates behind an
 * experiment what `From` ships as base game, `experiments`, their names, sorted; where `To` lacks
 * or renumbers any of `From`'s biomes, `biomes`; and where `To` lacks mob effects, `mob_effects`,
 * their ids, sorted. Generated by tools/generate_mappings.py.
 * @see ViaVersion MappingDataBase#load. */
template <int From, int To>
struct Mappings;

/** One hop's mappings, read from its generated `Mappings`.
 * @see ViaVersion MappingDataBase. */
template <int From, int To>
struct MappingDataBase {
    /** The id `To` gives the block `From` calls `id`. A block the hop leaves alone, such as an
     * add-on's, keeps its id. Every state of the hop's `block_states` is hashed on the first call. */
    static std::uint32_t getNewBlockStateId(std::uint32_t id)
    {
        static const auto mappings = [] {
            std::vector<std::pair<std::uint32_t, std::uint32_t>> result;
            for (const auto &update : Mappings<From, To>::block_states) {
                forEachBlock(update, [&](const bp::CompoundTag &states, const bp::CompoundTag &updated) {
                    const auto old_id = computeRawSerializationIdHashForNetwork(update.name, states);
                    const auto new_id = computeRawSerializationIdHashForNetwork(
                        update.rename.empty() ? update.name : update.rename, updated);
                    if (old_id != new_id) {
                        result.emplace_back(old_id, new_id);
                    }
                });
            }
            std::ranges::sort(result);
            return result;
        }();
        const auto it = std::ranges::lower_bound(mappings, id, {}, &std::pair<std::uint32_t, std::uint32_t>::first);
        return it != mappings.end() && it->first == id ? it->second : id;
    }

    /** The name `To` gives the block type `From` calls `name`, which is its fallback where `To` lacks it. */
    static std::string_view getNewBlockName(std::string_view name)
    {
        const auto &updates = Mappings<From, To>::block_states;
        const auto it = std::ranges::find(updates, name, &BlockStateUpdate::name);
        return it != updates.end() && !it->rename.empty() ? it->rename : name;
    }

    /** The name `To` gives the item `From` calls `name`, or none for an item `To` lacks. */
    static std::optional<std::string_view> getNewItemName(std::string_view name)
    {
        if constexpr (mapsItems()) {
            if (std::ranges::binary_search(Mappings<From, To>::items, name)) {
                return std::nullopt;
            }
        }
        return name;
    }

    /** Whether `To` lacks any of `From`'s items. */
    static consteval bool mapsItems()
    {
        return requires { Mappings<From, To>::items; };
    }

    /** The experiments `To` gates behind what `From` ships as base game. */
    static constexpr std::span<const std::string_view> getExperiments()
    {
        if constexpr (requires { Mappings<From, To>::experiments; }) {
            return Mappings<From, To>::experiments;
        }
        else {
            return {};
        }
    }

    /** The id `To` gives the biome `From` numbers `id`, its fallback's where `To` lacks it. */
    static std::uint32_t getNewBiomeId(std::uint32_t id)
    {
        if constexpr (mapsBiomes()) {
            const auto it = std::ranges::find(Mappings<From, To>::biomes, id, &BiomeUpdate::id);
            if (it != Mappings<From, To>::biomes.end()) {
                return it->new_id;
            }
        }
        return id;
    }

    /** The name `To` gives the biome `From` calls `name`, or none for a biome `To` lacks. */
    static std::optional<std::string_view> getNewBiomeName(std::string_view name)
    {
        if constexpr (mapsBiomes()) {
            const auto it = std::ranges::find(Mappings<From, To>::biomes, name, &BiomeUpdate::name);
            if (it != Mappings<From, To>::biomes.end() && !it->rename.empty()) {
                return std::nullopt;
            }
        }
        return name;
    }

    /** Whether `To` lacks or renumbers any of `From`'s biomes. */
    static consteval bool mapsBiomes()
    {
        return requires { Mappings<From, To>::biomes; };
    }

    /** The id `To` gives the mob effect `From` numbers `id`, or none for an effect `To` lacks. */
    static std::optional<std::int32_t> getNewMobEffectId(std::int32_t id)
    {
        if constexpr (mapsMobEffects()) {
            if (std::ranges::binary_search(Mappings<From, To>::mob_effects, id)) {
                return std::nullopt;
            }
        }
        return id;
    }

    /** Whether `To` lacks any of `From`'s mob effects. */
    static consteval bool mapsMobEffects()
    {
        return requires { Mappings<From, To>::mob_effects; };
    }
};

/** The mappings from `From` to `To`, through the `MappingDataBase` of each hop between them.
 * @see ViaVersion MappingData. */
template <int From, int To>
struct MappingData {
    static std::uint32_t getNewBlockStateId(std::uint32_t id)
    {
        if constexpr (From == To) {
            return id;
        }
        else {
            constexpr int next = step(From, To);
            return MappingData<next, To>::getNewBlockStateId(MappingDataBase<From, next>::getNewBlockStateId(id));
        }
    }

    static std::string_view getNewBlockName(std::string_view name)
    {
        if constexpr (From == To) {
            return name;
        }
        else {
            constexpr int next = step(From, To);
            return MappingData<next, To>::getNewBlockName(MappingDataBase<From, next>::getNewBlockName(name));
        }
    }

    static std::optional<std::string_view> getNewItemName(std::string_view name)
    {
        if constexpr (From == To) {
            return name;
        }
        else {
            constexpr int next = step(From, To);
            const auto mapped = MappingDataBase<From, next>::getNewItemName(name);
            return mapped ? MappingData<next, To>::getNewItemName(*mapped) : std::nullopt;
        }
    }

    /** Whether some hop between `From` and `To` maps an item. */
    static consteval bool mapsItems()
    {
        if constexpr (From == To) {
            return false;
        }
        else {
            return MappingDataBase<From, step(From, To)>::mapsItems() || MappingData<step(From, To), To>::mapsItems();
        }
    }

    /** The experiments of every hop between `From` and `To`. */
    static std::vector<std::string_view> getExperiments()
    {
        if constexpr (From == To) {
            return {};
        }
        else {
            constexpr int next = step(From, To);
            auto experiments = MappingData<next, To>::getExperiments();
            const auto hop = MappingDataBase<From, next>::getExperiments();
            experiments.insert(experiments.end(), hop.begin(), hop.end());
            return experiments;
        }
    }

    /** Whether some hop between `From` and `To` names an experiment. */
    static consteval bool enablesExperiments()
    {
        if constexpr (From == To) {
            return false;
        }
        else {
            return !MappingDataBase<From, step(From, To)>::getExperiments().empty() ||
                   MappingData<step(From, To), To>::enablesExperiments();
        }
    }

    static std::uint32_t getNewBiomeId(std::uint32_t id)
    {
        if constexpr (From == To) {
            return id;
        }
        else {
            constexpr int next = step(From, To);
            return MappingData<next, To>::getNewBiomeId(MappingDataBase<From, next>::getNewBiomeId(id));
        }
    }

    static std::optional<std::string_view> getNewBiomeName(std::string_view name)
    {
        if constexpr (From == To) {
            return name;
        }
        else {
            constexpr int next = step(From, To);
            const auto mapped = MappingDataBase<From, next>::getNewBiomeName(name);
            return mapped ? MappingData<next, To>::getNewBiomeName(*mapped) : std::nullopt;
        }
    }

    /** Whether some hop between `From` and `To` maps a biome. */
    static consteval bool mapsBiomes()
    {
        if constexpr (From == To) {
            return false;
        }
        else {
            return MappingDataBase<From, step(From, To)>::mapsBiomes() || MappingData<step(From, To), To>::mapsBiomes();
        }
    }

    static std::optional<std::int32_t> getNewMobEffectId(std::int32_t id)
    {
        if constexpr (From == To) {
            return id;
        }
        else {
            constexpr int next = step(From, To);
            const auto mapped = MappingDataBase<From, next>::getNewMobEffectId(id);
            return mapped ? MappingData<next, To>::getNewMobEffectId(*mapped) : std::nullopt;
        }
    }

    /** Whether some hop between `From` and `To` maps a mob effect. */
    static consteval bool mapsMobEffects()
    {
        if constexpr (From == To) {
            return false;
        }
        else {
            return MappingDataBase<From, step(From, To)>::mapsMobEffects() ||
                   MappingData<step(From, To), To>::mapsMobEffects();
        }
    }
};

} // namespace endweave
